import {audioAvailabilityCopy,routineGroups,audioCheckMarkup,deviceTestMarkup} from './audio-guidance.mjs';
import {earlyLanguages,earlyRoutines,earlyStages,earlySelection,earlyLines,earlyAudioIndex} from './early-language-data.mjs';
import {localSpeechSession,stopLanguageAudio,showSpeechStopResult} from './language-audio.mjs';

export function mountEarlyLanguage(root,{onExit=()=>{},onSelection=()=>{}}={}){
 const doc=root.ownerDocument,win=doc.defaultView;
 let opened=false,language='zh',activity='hello',stage='4-6',phase='ready',step=0,curtain=false,lastLine=null,setupOpen=true,blocked=false,engine=null,unsubscribe=null,voiceListener=null;
 const cancel=()=>{if(!engine)return true;const ok=engine.stop();blocked=!ok;showSpeechStopResult(doc,engine,ok);return ok;};
 const focus=selector=>root.querySelector(selector)?.focus();
 const selected=()=>earlySelection(language,activity,stage);
 const contextMarkup=(showActivity=false)=>{const v=selected();return `<div class="early-context" aria-label="Momento seleccionado"><p>Idioma<strong id="early-context-language">${v.language.id==='pt'?'Portugués de Brasil':v.language.name}</strong></p><p>Etapa orientativa<strong id="early-context-stage">${v.stage.label.split(' · ')[0]}</strong></p>${showActivity?`<p>Actividad<strong>${v.routine.name}</strong></p>`:''}</div>`;};
 function audioStatus(){
  if(!opened||!engine)return;
  const {language:l}=selected(),a=engine.availability('early-'+language),s=engine.state;
  if(s.phase==='error'&&s.message.startsWith('No se pudo confirmar')){blocked=true;showSpeechStopResult(doc,engine,false);}
  const copy=audioAvailabilityCopy(a,l),availability=root.querySelector('#early-voice'),heading=root.querySelector('#early-audio-check-title'),check=root.querySelector('.early-audio-check');
  if(availability)availability.textContent=copy.detail;if(heading)heading.textContent=copy.title;if(check)check.dataset.availability=copy.status;
  root.querySelectorAll('[data-early-listen]').forEach(b=>{b.disabled=!a.available||blocked||phase!=='active'||step!==0;});
  const repeat=root.querySelector('#early-repeat');if(repeat)repeat.disabled=!a.available||blocked||lastLine===null||phase!=='active'||step!==0;
  const status=root.querySelector('#early-audio-status');if(status)status.textContent=s.phase==='idle'&&s.message.startsWith('Reproducción terminada')?'Terminó el apoyo hablado. Ahora tu voz y una pausa; no empieza otra frase automáticamente.':s.message;
 }
 const lineMarkup=(line,i)=>`<article class="early-phrase" data-phrase-index="${i}" data-phrase-role="${line.conditional?'response':'invitation'}"><p class="early-target" lang="${language}">${line.text}</p>${line.pinyin?`<p class="early-pinyin" lang="zh-Latn">${line.pinyin}</p>`:''}<p class="early-translation">${line.translation}</p><button type="button" class="action secondary" data-early-listen="${i}">Escuchar frase hablada${line.conditional?' · respuesta opcional':''}</button></article>`;
 const textLine=line=>`<article class="early-spoken-line"><p class="early-target" lang="${language}">${line.text}</p>${line.pinyin?`<p class="early-pinyin" lang="zh-Latn">${line.pinyin}</p>`:''}<p class="early-translation">${line.translation}</p></article>`;
 function routineMarkup(lines,spoken=false){const groups=routineGroups(lines);const render=items=>items.map(({line,index})=>spoken?textLine(line):lineMarkup(line,index)).join('');return `<div class="early-turns" data-has-response="${groups.response.length>0}"><section class="early-invitation" aria-label="Invitación del adulto"><h3>Una invitación</h3><p class="early-turn-note">Puedes ofrecer una frase y dejar un turno.</p><div class="early-phrase-grid">${render(groups.invitation)}</div></section>${groups.response.length?`<section class="early-optional-response" aria-label="Respuesta opcional del adulto"><h3>Respuesta opcional</h3><p class="early-condition">Solo si hubo un sonido espontáneo. Puedes omitir esta frase; no hace falta provocar una respuesta.</p><div class="early-phrase-grid">${render(groups.response)}</div></section>`:''}<aside class="early-silence" aria-label="Silencio y pausa"><h3>También vale el silencio</h3><p>Si no hubo un sonido, acompaña el silencio. No hace falta repetir, contestar ni completar nada.</p></aside></div>`;}
 const momentHeading=()=>phase==='ready'?'Antes de empezar':phase==='paused'?'Momento en pausa':phase==='closed'?'Cerrado por hoy':['Escucha si quieres','Ahora, tu voz','Deja una pausa'][step];
 function render(){
  if(!opened)return;
  const {language:l,routine:r,stage:s}=selected(),lines=earlyLines(language,activity);
  root.dataset.phase=phase;root.classList.toggle('early-curtain',curtain);
  if(curtain){root.innerHTML=`<div class="early-away">${contextMarkup(true)}<p class="eyebrow">SIGUE CARA A CARA</p><h1 tabindex="-1">Tu voz, su turno.</h1><p>El audio está detenido. Puedes guardar el dispositivo o bloquear su pantalla y seguir con tu voz, sin esperar una respuesta.</p><button type="button" class="action primary" id="early-uncover">Volver a la guía del adulto</button><button type="button" class="action secondary" id="early-exit">Salir de este momento</button></div>`;bind();focus('h1');return;}
  root.innerHTML=`<header class="early-heading"><div class="early-heading-top"><p class="eyebrow">IDIOMAS · ADULTO</p><button type="button" class="action secondary" id="early-exit" aria-label="Volver a mi espacio">← Mi espacio</button></div><h1 tabindex="-1" aria-describedby="early-context-language early-context-stage">${r.name}</h1><p class="early-heading-copy">Acompaña en persona; el bebé no necesita mirar ni repetir.</p></header>${contextMarkup()}<div class="early-layout">${audioCheckMarkup()}<details class="early-setup" ${phase==='ready'&&setupOpen?'open':''}><summary>Cambiar idioma, etapa o actividad</summary><div class="early-setup-fields"><label for="early-language">Idioma</label><select id="early-language">${earlyLanguages.map(x=>`<option value="${x.id}" ${x.id===language?'selected':''}>${x.name} · ${x.native}</option>`).join('')}</select><label for="early-stage">Forma de acompañar</label><select id="early-stage">${earlyStages.map(x=>`<option value="${x.id}" ${x.id===stage?'selected':''}>${x.label}</option>`).join('')}</select><p class="quiet">Franjas flexibles que se solapan; elige según el momento. No son niveles, requisitos ni una evaluación.</p><label for="early-routine">Actividad en persona</label><select id="early-routine">${earlyRoutines.map(x=>`<option value="${x.id}" ${x.id===activity?'selected':''}>${x.name}</option>`).join('')}</select><p>${s.guide}</p><details><summary>Antes de escuchar</summary><p>Empieza con volumen suave y un entorno tranquilo. Mantén el dispositivo lejos del oído y evita auriculares para el bebé. Ningún ajuste de la app garantiza un volumen seguro.</p><p>Habla en el idioma en el que te sientas cómodo. El audio es apoyo para el adulto, no sustitución de tu presencia ni una clase formal para el bebé.</p><p>No guardamos esta selección ni respuestas del bebé. No usamos micrófono, cámara ni grabaciones.</p></details></div></details><section class="early-moment" aria-labelledby="early-moment-title"><p class="eyebrow">${l.name.toUpperCase()} · ${phase==='ready'?'UNA INVITACIÓN BREVE':phase==='paused'?'EN PAUSA':phase==='closed'?'CERRADO POR HOY':'A TU RITMO'}</p><h2 id="early-moment-title" tabindex="-1">${momentHeading()}</h2>${phase==='ready'?`<p>${r.action}</p><p class="early-ready-note">Sin reloj ni respuestas que conseguir.</p><button type="button" class="action primary" id="early-start">Iniciar este momento</button><details class="early-how"><summary>Cómo acompañar este momento</summary><ol class="early-flow"><li>Escucha una referencia hablada si la necesitas.</li><li>Habla, canta o recita tú.</li><li>Deja una pausa y sigue su interés.</li></ol><p class="early-note">Unos pocos turnos pueden bastar. No hay reloj ni duración que cumplir, ni promesas de fluidez o desarrollo acelerado.</p></details>`:phase==='paused'?'<p>El audio se ha detenido. Puedes descansar, volver a la guía o cerrar. Retomar no reproduce nada por sí solo.</p><div class="controls"><button type="button" class="action primary" id="early-resume">Retomar sin reproducción automática</button><button type="button" class="action secondary" id="early-stop">Terminar por hoy</button></div>':phase==='closed'?'<p>No hay nada que completar ni una respuesta que registrar. Puedes seguir jugando en persona o dejarlo aquí.</p><button type="button" class="action primary" id="early-reset">Preparar otro momento</button>':`<ol class="early-steps" aria-label="Secuencia del adulto"><li ${step===0?'aria-current="step"':''}>1 · Escucha</li><li ${step===1?'aria-current="step"':''}>2 · Tu voz</li><li ${step===2?'aria-current="step"':''}>3 · Pausa y escucha</li></ol>${step===0?`<p>Puedes escuchar una referencia o pasar directamente a tu propia voz.</p><details class="early-pronunciation"><summary>Ver las frases y el apoyo hablado · opcional</summary><p>Pronunciación hablada opcional. Cada pulsación reproduce una sola frase; no hay canción grabada ni reproducción en cadena.</p><p class="quiet">Volumen suave, dispositivo lejos del oído y sin auriculares para el bebé.</p>${routineMarkup(lines)}<button type="button" class="action secondary" id="early-repeat">Repetir la última frase manualmente</button></details><button type="button" class="action primary early-next" id="early-next">Ahora, con mi voz →</button>`:step===1?`<p>${r.action}</p><div class="early-verse"><p class="eyebrow">RECITADO ORIGINAL · PARA TU VOZ</p>${routineMarkup(lines,true)}</div><p>Puedes recitarlo o improvisar una melodía sencilla en persona. Repite solo si resulta agradable y deja silencio entre frases. ${language==='zh'?'Para la pronunciación del mandarín, conserva los tonos de la referencia hablada: una melodía no es un modelo de los tonos.':''}</p><button type="button" class="action primary early-next" id="early-next">Dejar un turno en silencio →</button>`:`<p class="early-wait">${r.wait}</p><p>No hay una respuesta correcta ni hace falta completar otra actividad.</p><button type="button" class="action primary" id="early-stop">Cerrar este momento</button>`}<div class="early-session-actions"><button type="button" class="action secondary" id="early-pause">Pausar y detener audio</button><button type="button" class="action secondary" id="early-screen">Apartar la guía</button><button type="button" class="action secondary" id="early-stop-now">Detener y terminar</button></div>`}<p id="early-audio-status" role="status" aria-live="polite" aria-atomic="true"></p>${deviceTestMarkup()}<details class="early-observe"><summary>Cuándo hacer una pausa</summary><p>Si se inquieta, llora, aparta repetidamente la mirada o parece cansado o incómodo, detén el audio y atiéndelo. No necesitas conseguir atención, una sonrisa o un sonido.</p><p>Al bloquear la pantalla, cambiar de pestaña o salir se solicita detener la voz. Si quieres apagar la pantalla, sigue el juego con tu propia voz; no prometemos reproducción en segundo plano.</p></details><details><summary>Alcance y fuentes</summary><p>Textos originales para el adulto, pendientes de revisión humana de uso y pronunciación. El dispositivo no canta ni evalúa al bebé. La exposición pasiva no se presenta como eficaz.</p><p><a href="https://www2.hse.ie/babies-children/checks-milestones/communication-development/0-12-months/" target="_blank" rel="noopener noreferrer">HSE · interacción y pausas</a> · <a href="https://raisingchildren.net.au/babies/development/language-development/language-3-12-months" target="_blank" rel="noopener noreferrer">Raising Children Network · lenguaje</a></p></details></section></div>`;
  bind();audioStatus();
 }
 function updateSelection(event){const origin=event.target.id;cancel();setupOpen=true;phase='ready';step=0;lastLine=null;language=root.querySelector('#early-language').value;activity=root.querySelector('#early-routine').value;stage=root.querySelector('#early-stage').value;const v=selected();language=v.language.id;activity=v.routine.id;stage=v.stage.id;onSelection({language,stage});render();focus('#'+origin);}
 function bind(){
  const on=(id,fn)=>root.querySelector('#'+id)?.addEventListener('click',fn);
  root.querySelectorAll('select').forEach(x=>x.onchange=updateSelection);
  on('early-exit',()=>close(true));on('early-start',()=>{phase='active';step=0;render();focus('#early-moment-title');});
  on('early-resume',()=>{phase='active';render();focus('#early-moment-title');});
  on('early-pause',()=>pause());on('early-stop',stop);on('early-stop-now',stop);
  on('early-reset',()=>{cancel();setupOpen=false;phase='ready';step=0;lastLine=null;render();focus('#early-moment-title');});
  on('early-next',()=>{cancel();step=Math.min(2,step+1);render();focus('#early-moment-title');});
  on('early-screen',()=>{cancel();phase='paused';curtain=true;render();});
  on('early-uncover',()=>{curtain=false;render();focus('#early-moment-title');});
  root.querySelectorAll('[data-early-listen]').forEach(b=>b.onclick=()=>speak(Number(b.dataset.earlyListen)));
  on('early-voices-refresh',()=>{engine.refresh();blocked=engine.state.phase==='error';showSpeechStopResult(doc,engine,!blocked);audioStatus();focus('#early-audio-check-title');});
  on('early-repeat',()=>{if(lastLine!==null)speak(lastLine);});
 }
 function speak(index){if(!opened||phase!=='active'||step!==0||doc.hidden||blocked)return;const position=earlyAudioIndex(activity,index);if(position===null)return;if(engine.play('early-'+language,position)){lastLine=index;showSpeechStopResult(doc,engine,true);}audioStatus();}
 function pause(){if(!opened||phase!=='active')return;cancel();phase='paused';render();focus('#early-moment-title');}
 function stop(){cancel();phase='closed';lastLine=null;render();focus('#early-moment-title');}
 function close(notify=false){if(!opened)return;opened=false;stopLanguageAudio(doc);root.hidden=true;curtain=false;doc.body.classList.remove('early-audio-mode');if(notify)onExit();}
 function open(selection={}){
  setupOpen=!(earlyLanguages.some(l=>l.id===selection?.language)&&earlyStages.some(s=>s.id===selection?.stage));
  if(earlyLanguages.some(l=>l.id===selection?.language))language=selection.language;
  if(earlyStages.some(s=>s.id===selection?.stage))stage=selection.stage;
  if(earlyRoutines.some(r=>r.id===selection?.activity))activity=selection.activity;
  onSelection({language,stage});
  stopLanguageAudio(doc);const speech=localSpeechSession(doc);engine=speech.engine;opened=true;phase='ready';step=0;lastLine=null;curtain=false;blocked=engine.state.phase==='error';root.hidden=false;doc.body.classList.add('early-audio-mode');
  unsubscribe?.();voiceListener&&engine.synthesis?.removeEventListener?.('voiceschanged',voiceListener);
  unsubscribe=engine.subscribe(audioStatus);voiceListener=()=>{engine.refresh();blocked=engine.state.phase==='error';if(phase==='active'){phase='paused';render();}else audioStatus();};engine.synthesis?.addEventListener?.('voiceschanged',voiceListener);
  speech.dispose=()=>{unsubscribe?.();unsubscribe=null;engine.synthesis?.removeEventListener?.('voiceschanged',voiceListener);voiceListener=null;};
  render();focus('h1');root.scrollIntoView?.({block:'start'});
 }
 doc.addEventListener('visibilitychange',()=>{if(doc.hidden)pause();});win.addEventListener('pagehide',()=>{if(opened){cancel();phase='paused';}});win.addEventListener('popstate',()=>close(false));win.addEventListener('hashchange',()=>close(false));
 doc.addEventListener('click',e=>{if(opened&&!root.contains(e.target)&&e.target.closest?.('a,[data-route],[data-dashboard-route],[data-band],#welcome-home,#welcome-explore'))close(false);},true);
 root.addEventListener('keydown',e=>{if(e.key==='Escape'&&curtain){e.preventDefault();curtain=false;render();focus('#early-moment-title');}});
 return {open,close,get state(){return {opened,language,activity,stage,phase,step,curtain};}};
}
